($f$080b7013-14b2-4fd8-be8b-f567db3cdb39$f$, 5412152, $f$All The Pleasures Prove$f$, ARRAY[$f$Laliandra$f$]::text[], ARRAY[$f$Think of England - K. J. Charles$f$]::text[], NULL, ARRAY[]::text[], $f$Archie was late, and Daniel was going to have to kill him, that was all there was to it. It wasn’t that he lacked for entertainment, or comfort, or anything at all in Archie’s flat, but an appointment was an appointment, and Archie was late.$f$, 11829, 1, 1, true, 3, false, $f$2025-05-04T13:49:16.865+00:00$f$, $f$2025-05-04T13:49:16.867+00:00$f$, $f$2015-12-12T00:00:00.000+00:00$f$, false, false, true, NULL, NULL, ARRAY[]::text[]),
